mapper.select:
SELECT id, initiation_id, wbs_task_id, period, pv, ev, ac, bac, cpi, spi, cv, sv, eac, vac, etc, tcpi, alert_level, alert_reason, measure_date, remark, tenant_id, provider_trace_id, created_at, updated_at, deleted
FROM pmis_evm_measure
WHERE initiation_id = #{initiationId}

      AND wbs_task_id = #{wbsTaskId}
      AND wbs_task_id IS NULL

  AND period = #{period}
  AND deleted = 0
LIMIT 1
